def _dl(a:str,b:str,m:int)->int:
    if abs(len(a)-len(b))>m:return m+1
    p2=None;p=list(range(len(b)+1))
    for i in range(1,len(a)+1):
        c=[i]+[0]*len(b)
        for j in range(1,len(b)+1):
            c[j]=min(p[j]+1,c[j-1]+1,p[j-1]+(a[i-1]!=b[j-1]));c[j]=min(c[j],p2[j-2]+1) if i>1 and j>1 and a[i-1]==b[j-2] and a[i-2]==b[j-1] else c[j]
        p2,p=p,c
    return p[-1]
@lru_cache(8192)
def _fix(w:str)->str:
    w=ABBR.get(w,w)
    return w if len(w)<5 or w in LEX or w in KEEP or not w.isalpha() else next((x for x in sorted(LEX) if x[0]==w[0] and _dl(w,x,2 if min(len(w),len(x))>=9 else 1)<=(2 if min(len(w),len(x))>=9 else 1)),w)
def norm(s:str)->str:
    t=re.sub(r"[\U0001F602\U0001F923\U0001F480]",' lol ',(s or '').lower());t=re.sub(r"[’‘`´]","'",t).replace("'",'')
    t=re.sub(r"[.!?;:\n]+",' . ',t);t=t.replace(',',' , ').replace('&',' and ');t=re.sub(r"[^a-z0-9 .,]",' ',t)
    t=' '.join(_fix(w) for w in t.split())
    for a,b in MW:t=re.sub(a,b,t)
    return ' '+re.sub(r"\s+",' ',t).strip()+' '
