CAT={'unresp':'medical','unresp_multi':'medical','unresp_child':'child','water':'medical','breath':'medical','allergy':'medical','choking':'medical','chest':'medical','stroke':'medical','bleed':'medical','wound':'medical','overdose':'medical','poison':'poison','battery':'poison','seizure':'medical','fall':'medical','heat':'medical','suicide':'suicide','suicide_other':'suicide','suicide_od':'suicide','suicide_cut':'suicide','diabetic':'medical','head':'medical','burn':'medical','electric':'medical','cold':'medical','crash':'medical','birth':'medical','preg':'medical','bite':'poison','ice':'child','trapped':'child','fire_car':'fire','wildfire':'fire','child_danger':'child','seizure_self':'medical','violence':'violence','intruder':'violence','shooter':'violence','child_abuse':'child','fire':'fire','fire_grease':'fire','fire_clothes':'fire','gas':'gas','co':'gas','child_car':'child','child_missing':'child','general':'medical'}
