    if (HYPOS if sui else HYPO).search(re.sub(r"\b(know|tell|sure|check|checking|see|seeing|find out|wonder|wondering|unsure|asking|ask|decide|figure out) (?:if|whether)\b",r"\1 whether",t)) and not URGS.search(t):return 'hypo'
