    sid=sui and SIDE.search(t)
    te=re.sub(r"\b(?:dont know|do not know|not sure|no idea|unsure|cant tell|idk) (?:how|what|if|whether)\b",' unsure',t);e=None if sid else EDU.search(te)
    if e and (h['gen'] or h['k'] is None) and (e.start()<h['s'] or not h['P']) and not URGS.search(t):return 'edu'
    if not sid and EDUS.search(te) and not h['P'] and not URGS.search(t):return 'edu'
