def neutral(message:str)->str:return "I'm not sure about that one yet." if QN.search(message or '') else "Thanks for sharing that. Tell me more?"
def guard_stream(message:str,chunks:Iterable[str])->Iterator[str]:
    if detect(message or ''):yield from chunks;return
    st={'said':False,'held':''}
    def keep(s:str)->str:
        if not s.strip():return s if st['said'] else ''
        if OUT.search(s):return ''
        if not st['said'] and re.fullmatch(r"\s*\(.*\)\s*",s,re.S):st['held']+=s;return ''
        r=('' if st['said'] else st['held'])+s;st['said']=True;st['held']='';return r
    buf=''
    for c in chunks:
        buf+=c or ''
        while (m:=SEND.search(buf)):
            r=keep(buf[:m.end()]);buf=buf[m.end():]
            if r:yield r
    r=keep(buf) if buf else ''
    if r:yield r
    if not st['said']:yield neutral(message)
def guard(message:str,text:str)->str:return ''.join(guard_stream(message,[text or '']))
